// Procedural canyon terrain. Everything is periodic in z with period L so the
// flythrough can loop seamlessly.

export const L = 320; // tile length along z (metres)
export const X = 160; // tile width along x
const P = (2 * Math.PI) / L;

function hash2(ix: number, iz: number): number {
  let h = (Math.imul(ix, 374761393) + Math.imul(iz, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967295;
}

function fade(t: number): number {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

/** Value noise in [0,1], periodic in z with period L. L/cs must be an integer. */
export function vnoise(x: number, z: number, cs: number): number {
  const gx = x / cs;
  const gz = z / cs;
  const pz = Math.round(L / cs);
  const ix = Math.floor(gx);
  const iz = Math.floor(gz);
  const fx = fade(gx - ix);
  const fz = fade(gz - iz);
  const z0 = ((iz % pz) + pz) % pz;
  const z1 = (z0 + 1) % pz;
  const a = hash2(ix, z0);
  const b = hash2(ix + 1, z0);
  const c = hash2(ix, z1);
  const d = hash2(ix + 1, z1);
  const top = a + (b - a) * fx;
  const bot = c + (d - c) * fx;
  return top + (bot - top) * fz;
}

export function fbm(x: number, z: number, cs: number, oct: number): number {
  let sum = 0;
  let amp = 0.5;
  let norm = 0;
  let c = cs;
  for (let i = 0; i < oct; i++) {
    sum += amp * vnoise(x + i * 17.3, z + i * 9.1, c);
    norm += amp;
    amp *= 0.5;
    c *= 0.5;
  }
  return sum / norm;
}

export function centerX(z: number): number {
  return 12 * Math.sin(3 * P * z + 0.4) + 3.5 * Math.sin(5 * P * z + 1.3);
}

export function halfWidth(z: number): number {
  return 11 + 2.5 * Math.sin(2 * P * z + 0.5) + 1.0 * Math.sin(7 * P * z + 2);
}

/** Horizontal distance past the canyon wall base (0 on the floor). */
export function wallDist(x: number, z: number): number {
  const c = centerX(z);
  const warp = 5 * (fbm(x, z, 20, 3) - 0.5) + 1.6 * (vnoise(x, z, 5) - 0.5);
  const u = Math.abs(x - c) + warp - halfWidth(z);
  return u > 0 ? u : 0;
}

function smoothstep(a: number, b: number, v: number): number {
  const t = Math.min(1, Math.max(0, (v - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

const TIER = 5.5;

export function heightAt(x: number, z: number): number {
  const u = wallDist(x, z);
  const c = centerX(z);
  const dch = x - (c + 2.2 * Math.sin(9 * P * z));
  let h =
    (fbm(x, z, 20, 3) - 0.5) * 0.9 +
    (vnoise(x, z, 2.5) - 0.5) * 0.14 +
    (vnoise(x, z, 0.625) - 0.5) * 0.04 -
    0.35 * Math.exp(-(dch * dch) / 8);
  if (u > 0) {
    const hmax = 34 + 22 * fbm(x, z, 40, 3);
    const h0 = hmax * (1 - Math.exp(-u / 8));
    const shift = 6 * (fbm(x, z, 10, 2) - 0.5) * Math.min(u / 3, 1);
    const tt = Math.max((h0 + shift) / TIER, 0);
    const fl = Math.floor(tt);
    const fr = tt - fl;
    h += (fl + smoothstep(0.35, 1, fr)) * TIER;
    h += (fbm(x, z, 2.5, 3) - 0.5) * 1.8 * Math.min(u / 3, 1);
    h += 1.0 * (1 - Math.exp(-u / 2.5));
  }
  return h;
}

// Sandstone strata palette (sRGB, 0..1).
const PAL: ReadonlyArray<readonly [number, number, number]> = [
  [0.8, 0.55, 0.35],
  [0.7, 0.33, 0.2],
  [0.58, 0.27, 0.19],
  [0.85, 0.66, 0.45],
  [0.5, 0.22, 0.17],
  [0.72, 0.45, 0.3],
];

export function strataColor(
  band: number,
  out: [number, number, number],
): [number, number, number] {
  const i = Math.floor(band);
  const f = smoothstep(0.75, 1, band - i);
  const a = PAL[Math.floor(hash2(i, 7) * PAL.length) % PAL.length];
  const b = PAL[Math.floor(hash2(i + 1, 7) * PAL.length) % PAL.length];
  out[0] = a[0] + (b[0] - a[0]) * f;
  out[1] = a[1] + (b[1] - a[1]) * f;
  out[2] = a[2] + (b[2] - a[2]) * f;
  return out;
}

const SAND: readonly [number, number, number] = [0.78, 0.6, 0.42];
const GRAVEL: readonly [number, number, number] = [0.6, 0.5, 0.43];

export interface TerrainData {
  positions: Float32Array;
  normals: Float32Array;
  colors: Float32Array;
  uvs: Float32Array;
  indices: Uint32Array;
}

export function buildTerrain(nx: number, nz: number): TerrainData {
  const dx = X / nx;
  const dz = L / nz;
  const w = nx + 3;
  const hs = new Float32Array(w * (nz + 3));
  for (let j = -1; j <= nz + 1; j++) {
    for (let i = -1; i <= nx + 1; i++) {
      hs[(j + 1) * w + (i + 1)] = heightAt(-X / 2 + i * dx, j * dz);
    }
  }
  const count = (nx + 1) * (nz + 1);
  const positions = new Float32Array(count * 3);
  const normals = new Float32Array(count * 3);
  const colors = new Float32Array(count * 3);
  const uvs = new Float32Array(count * 2);
  const tmp: [number, number, number] = [0, 0, 0];
  let v = 0;
  for (let j = 0; j <= nz; j++) {
    for (let i = 0; i <= nx; i++, v++) {
      const x = -X / 2 + i * dx;
      const z = j * dz;
      const k = (j + 1) * w + (i + 1);
      const h = hs[k];
      const gx = (hs[k + 1] - hs[k - 1]) / (2 * dx);
      const gz = (hs[k + w] - hs[k - w]) / (2 * dz);
      const inv = 1 / Math.sqrt(gx * gx + 1 + gz * gz);
      const ny = inv;
      positions[v * 3] = x;
      positions[v * 3 + 1] = h;
      positions[v * 3 + 2] = z;
      normals[v * 3] = -gx * inv;
      normals[v * 3 + 1] = ny;
      normals[v * 3 + 2] = -gz * inv;
      uvs[v * 2] = (x + X / 2) / X;
      uvs[v * 2 + 1] = z / L;

      // colour
      const band = h * 0.3 + 2.2 * fbm(x, z, 20, 2) + 0.35 * vnoise(x, z, 1.25);
      strataColor(band, tmp);
      const u = wallDist(x, z);
      const flat = smoothstep(0.7, 0.95, ny);
      let sandMix = flat * (u > 0 ? 0.7 : 1);
      if (u > 0) sandMix *= 1 - smoothstep(30, 50, h);
      const c = centerX(z);
      const dch = x - (c + 2.2 * Math.sin(9 * P * z));
      const gr = Math.exp(-(dch * dch) / 10) * (u > 0 ? 0 : 0.6);
      const lum = 0.92 + 0.16 * vnoise(x, z, 1.25);
      for (let q = 0; q < 3; q++) {
        let col = tmp[q] + (SAND[q] - tmp[q]) * sandMix;
        col = col + (GRAVEL[q] - col) * gr;
        col *= lum;
        colors[v * 3 + q] = Math.pow(Math.min(Math.max(col, 0), 1), 2.2);
      }
    }
  }
  const indices = new Uint32Array(nx * nz * 6);
  let n = 0;
  for (let j = 0; j < nz; j++) {
    for (let i = 0; i < nx; i++) {
      const a = j * (nx + 1) + i;
      const b = a + 1;
      const c = a + nx + 1;
      const d = c + 1;
      indices[n++] = a;
      indices[n++] = c;
      indices[n++] = b;
      indices[n++] = b;
      indices[n++] = c;
      indices[n++] = d;
    }
  }
  return { positions, normals, colors, uvs, indices };
}

import {
  BufferGeometry,
  CylinderGeometry,
  Float32BufferAttribute,
  IcosahedronGeometry,
  MeshStandardMaterial,
  Quaternion,
  Vector3,
} from 'three';
import { mergeGeometries, mergeVertices } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { strataColor } from './terrain';

export function makeRng(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function makeBoulderGeometry(seed: number): BufferGeometry {
  let g: BufferGeometry = new IcosahedronGeometry(1, 4);
  g.deleteAttribute('normal');
  g.deleteAttribute('uv');
  const pos = g.getAttribute('position');
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    let y = pos.getY(i);
    const z = pos.getZ(i);
    const r =
      1 +
      0.2 * Math.sin(2.3 * x + seed) * Math.sin(2.1 * y + seed * 1.7) +
      0.13 * Math.sin(4.1 * z + seed * 0.6) * Math.sin(3.7 * x + 2) +
      0.05 * Math.sin(9 * y + 3 * seed) * Math.sin(8 * z + seed);
    pos.setXYZ(i, x * r, y * r, z * r);
    y = pos.getY(i);
    if (y < -0.55) pos.setY(i, -0.55);
  }
  g = mergeVertices(g, 1e-4);
  g.computeVertexNormals();
  const p = g.getAttribute('position');
  const colors = new Float32Array(p.count * 3);
  const tmp: [number, number, number] = [0, 0, 0];
  for (let i = 0; i < p.count; i++) {
    strataColor(p.getY(i) * 1.6 + seed * 3.1, tmp);
    const dark = 0.75;
    for (let q = 0; q < 3; q++) colors[i * 3 + q] = Math.pow(tmp[q] * dark, 2.2);
  }
  g.setAttribute('color', new Float32BufferAttribute(colors, 3));
  return g;
}

export function makeShrubGeometry(seed: number): BufferGeometry {
  const rng = makeRng(seed);
  const parts: BufferGeometry[] = [];
  const up = new Vector3(0, 1, 0);
  const q = new Quaternion();

  const grow = (start: Vector3, dir: Vector3, len: number, radius: number, depth: number): void => {
    const g = new CylinderGeometry(radius * 0.55, radius, len, 5, 1);
    g.translate(0, len / 2, 0);
    q.setFromUnitVectors(up, dir);
    g.applyQuaternion(q);
    g.translate(start.x, start.y, start.z);
    parts.push(g);
    if (depth <= 0) return;
    const end = start.clone().addScaledVector(dir, len);
    const n = 2 + Math.floor(rng() * 2);
    for (let i = 0; i < n; i++) {
      const d = dir
        .clone()
        .add(new Vector3((rng() - 0.5) * 1.4, (rng() - 0.3) * 0.5, (rng() - 0.5) * 1.4))
        .normalize();
      grow(end, d, len * (0.62 + rng() * 0.15), radius * 0.62, depth - 1);
    }
  };

  const stems = 3 + Math.floor(rng() * 2);
  for (let i = 0; i < stems; i++) {
    const d = new Vector3((rng() - 0.5) * 1.2, 1, (rng() - 0.5) * 1.2).normalize();
    grow(new Vector3(0, -0.05, 0), d, 0.35 + rng() * 0.15, 0.028, 3);
  }
  const merged = mergeGeometries(parts, false);
  parts.forEach((p) => p.dispose());
  if (!merged) throw new Error('shrub merge failed');
  return merged;
}

export function makeRockMaterial(): MeshStandardMaterial {
  return new MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0 });
}

export function makeShrubMaterial(): MeshStandardMaterial {
  return new MeshStandardMaterial({ color: 0x6a5240, roughness: 1, metalness: 0 });
}

import {
  BufferGeometry,
  CanvasTexture,
  Color,
  DirectionalLight,
  FogExp2,
  Float32BufferAttribute,
  Group,
  HemisphereLight,
  Material,
  Mesh,
  MeshStandardMaterial,
  PCFSoftShadowMap,
  PerspectiveCamera,
  RepeatWrapping,
  Scene,
  SphereGeometry,
  ShaderMaterial,
  SRGBColorSpace,
  BackSide,
  NoToneMapping,
  Uint32BufferAttribute,
  Vector3,
  WebGLRenderer,
} from 'three';
import {
  L,
  X,
  buildTerrain,
  centerX,
  halfWidth,
  heightAt,
  wallDist,
} from './terrain';
import {
  makeBoulderGeometry,
  makeRng,
  makeRockMaterial,
  makeShrubGeometry,
  makeShrubMaterial,
} from './props';

declare global {
  interface Window {
    __EVAL_READY__?: boolean;
  }
}

const canvas = document.getElementById('app') as HTMLCanvasElement;
const renderer = new WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(1);
renderer.setSize(640, 360, false);
renderer.toneMapping = NoToneMapping;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = PCFSoftShadowMap;

const scene = new Scene();

// ---- colours (display / sRGB space) ----
const HORIZON: [number, number, number] = [0.78, 0.46, 0.54];
const fogColor = new Color().setRGB(HORIZON[0], HORIZON[1], HORIZON[2], SRGBColorSpace);
scene.fog = new FogExp2(fogColor, 0.0105);
scene.background = fogColor.clone();

const SUN = new Vector3(0.25, 0.2, -1).normalize(); // direction towards the sun
const sunViewDir = { value: new Vector3() };
const sunGlow = { value: new Vector3(0.9, 0.45, 0.18) };

// ---- sky dome ----
const skyMat = new ShaderMaterial({
  side: BackSide,
  depthWrite: false,
  fog: false,
  uniforms: {
    sunDir: { value: SUN.clone() },
    sunGlow: sunGlow,
    horizon: { value: new Vector3(HORIZON[0], HORIZON[1], HORIZON[2]) },
  },
  vertexShader: /* glsl */ `
    varying vec3 vDir;
    void main() {
      vDir = normalize(position);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: /* glsl */ `
    varying vec3 vDir;
    uniform vec3 sunDir;
    uniform vec3 sunGlow;
    uniform vec3 horizon;
    void main() {
      vec3 d = normalize(vDir);
      float e = max(d.y, 0.0);
      vec3 mid = vec3(0.50, 0.36, 0.62);
      vec3 zenith = vec3(0.06, 0.09, 0.30);
      vec3 col = mix(horizon, mid, smoothstep(0.0, 0.3, e));
      col = mix(col, zenith, smoothstep(0.2, 0.9, e));
      float s = max(dot(d, sunDir), 0.0);
      col += sunGlow * (0.35 * pow(s, 6.0) + 0.5 * pow(s, 32.0));
      col += vec3(1.0, 0.85, 0.6) * smoothstep(0.9993, 0.9998, s);
      // faint stars high up
      vec3 q = floor(d * 140.0);
      float h = fract(sin(dot(q, vec3(12.9898, 78.233, 37.719))) * 43758.5453);
      col += vec3(0.8) * step(0.9985, h) * smoothstep(0.45, 0.8, d.y) * 0.5;
      gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
    }
  `,
});
const sky = new Mesh(new SphereGeometry(500, 32, 16), skyMat);
sky.renderOrder = -1;
sky.frustumCulled = false;
scene.add(sky);

// ---- fog patch: haze that picks up warm in-scattering toward the sun ----
function patchFog<T extends Material>(mat: T): T {
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.sunViewDir = sunViewDir;
    shader.uniforms.sunGlow = sunGlow;
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <fog_pars_fragment>',
        `#include <fog_pars_fragment>
         uniform vec3 sunViewDir;
         uniform vec3 sunGlow;`,
      )
      .replace(
        '#include <fog_fragment>',
        `#ifdef USE_FOG
           float fogF = 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth);
           float sd = max(dot(normalize(-vViewPosition), sunViewDir), 0.0);
           vec3 fogCol2 = fogColor + sunGlow * (0.35 * pow(sd, 6.0) + 0.5 * pow(sd, 32.0));
           gl_FragColor.rgb = mix(gl_FragColor.rgb, fogCol2, fogF);
         #endif`,
      );
  };
  return mat;
}

// ---- lights ----
const hemi = new HemisphereLight(0x8a80d8, 0x8a5038, 2.0);
scene.add(hemi);

const sun = new DirectionalLight(0xff9e52, 5);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.15;
const SH_W = 85;
const SH_H = 50;
sun.shadow.camera.left = -SH_W;
sun.shadow.camera.right = SH_W;
sun.shadow.camera.top = SH_H;
sun.shadow.camera.bottom = -SH_H;
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 620;
sun.shadow.camera.updateProjectionMatrix();
scene.add(sun);
scene.add(sun.target);

// ---- detail texture (grain) ----
function makeGrain(): CanvasTexture {
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 256;
  const ctx = c.getContext('2d');
  if (!ctx) throw new Error('2d context unavailable');
  const img = ctx.createImageData(256, 256);
  const rng = makeRng(99);
  for (let i = 0; i < 256 * 256; i++) {
    const v = 0.8 + 0.2 * rng();
    const b = Math.round(255 * v);
    img.data[i * 4] = b;
    img.data[i * 4 + 1] = b;
    img.data[i * 4 + 2] = b;
    img.data[i * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const t = new CanvasTexture(c);
  t.wrapS = RepeatWrapping;
  t.wrapT = RepeatWrapping;
  t.repeat.set(X / 4, L / 4);
  t.colorSpace = SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

// ---- terrain tile ----
const NX = 240;
const NZ = 400;
const td = buildTerrain(NX, NZ);
const terrainGeo = new BufferGeometry();
terrainGeo.setAttribute('position', new Float32BufferAttribute(td.positions, 3));
terrainGeo.setAttribute('normal', new Float32BufferAttribute(td.normals, 3));
terrainGeo.setAttribute('color', new Float32BufferAttribute(td.colors, 3));
terrainGeo.setAttribute('uv', new Float32BufferAttribute(td.uvs, 2));
terrainGeo.setIndex(new Uint32BufferAttribute(td.indices, 1));

const terrainMat = patchFog(
  new MeshStandardMaterial({ vertexColors: true, map: makeGrain(), roughness: 1, metalness: 0 }),
);
const tile = new Group();
const terrain = new Mesh(terrainGeo, terrainMat);
terrain.castShadow = true;
terrain.receiveShadow = true;
tile.add(terrain);

// ---- props: boulders and dead shrubs ----
const rockMat = patchFog(makeRockMaterial());
const shrubMat = patchFog(makeShrubMaterial());
const boulderGeos = [1, 2, 3, 4, 5].map((s) => makeBoulderGeometry(s * 1.37));
const shrubGeos = [11, 12, 13, 14].map((s) => makeShrubGeometry(s));
const rng = makeRng(2024);

function onFloor(x: number, z: number, r: number): boolean {
  return (
    wallDist(x, z) <= 0.01 &&
    wallDist(x - r, z) <= 0.2 &&
    wallDist(x + r, z) <= 0.2 &&
    Math.abs(x - centerX(z)) < halfWidth(z) - 1
  );
}

let placed = 0;
for (let tries = 0; placed < 44 && tries < 600; tries++) {
  const z = rng() * L;
  const c = centerX(z);
  const x = c + (rng() * 2 - 1) * halfWidth(z);
  const big = rng() < 0.35;
  const s = big ? 1.6 + rng() * 1.8 : 0.35 + rng() * 0.9;
  if (!onFloor(x, z, s * 1.2)) continue;
  if (Math.abs(x - c) < 4.5 && s > 0.8) continue;
  const m = new Mesh(boulderGeos[Math.floor(rng() * boulderGeos.length)], rockMat);
  const sy = s * (0.6 + rng() * 0.4);
  m.scale.set(s * (0.9 + rng() * 0.4), sy, s * (0.9 + rng() * 0.4));
  m.rotation.y = rng() * Math.PI * 2;
  m.position.set(x, heightAt(x, z) + 0.3 * sy, z);
  m.castShadow = true;
  m.receiveShadow = true;
  tile.add(m);
  placed++;
}

placed = 0;
for (let tries = 0; placed < 80 && tries < 1200; tries++) {
  const z = rng() * L;
  const c = centerX(z);
  const x = c + (rng() * 2 - 1) * halfWidth(z);
  if (!onFloor(x, z, 0.8)) continue;
  const m = new Mesh(shrubGeos[Math.floor(rng() * shrubGeos.length)], shrubMat);
  const s = 0.7 + rng() * 1.0;
  m.scale.setScalar(s);
  m.rotation.y = rng() * Math.PI * 2;
  m.position.set(x, heightAt(x, z), z);
  m.castShadow = true;
  m.receiveShadow = true;
  tile.add(m);
  placed++;
}

// tile covers z in [0, L]; a copy covers [-L, 0]
const tileB = tile.clone();
tileB.position.z = -L;
scene.add(tile, tileB);

// ---- camera flythrough ----
const camera = new PerspectiveCamera(55, 640 / 360, 0.3, 800);
const LOOP = 80; // seconds per loop
const TWO_PI = Math.PI * 2;

function drift(t: number): number {
  return 2.2 * Math.sin((TWO_PI * 3 * t) / LOOP) + 0.8 * Math.sin((TWO_PI * 7 * t) / LOOP + 1);
}

const tmpTarget = new Vector3();
const fwd = new Vector3();
const lx = new Vector3();
const ly = new Vector3();
const lc = new Vector3();
const UP = new Vector3(0, 1, 0);

function updateCamera(t: number): void {
  const frac = (((t / LOOP) % 1) + 1) % 1;
  const z = L * (1 - frac);
  camera.position.set(
    centerX(z) + drift(t),
    1.8 + 0.1 * Math.sin((TWO_PI * 9 * t) / LOOP),
    z,
  );
  const zt = z - 18;
  tmpTarget.set(centerX(zt) + 0.7 * drift(t + 4.5), 6.5, zt);
  camera.lookAt(tmpTarget);
  camera.rotateZ(0.015 * Math.sin((TWO_PI * 4 * t) / LOOP));
  camera.updateMatrixWorld();
}

function updateLighting(): void {
  camera.getWorldDirection(fwd);
  fwd.y = 0;
  fwd.normalize();
  lc.copy(camera.position).addScaledVector(fwd, 45);
  lc.y = 22;
  lx.crossVectors(UP, SUN).normalize();
  ly.crossVectors(SUN, lx);
  const tx = (2 * SH_W) / 2048;
  const ty = (2 * SH_H) / 2048;
  const cx = Math.round(lc.dot(lx) / tx) * tx;
  const cy = Math.round(lc.dot(ly) / ty) * ty;
  const cz = lc.dot(SUN);
  lc.set(0, 0, 0).addScaledVector(lx, cx).addScaledVector(ly, cy).addScaledVector(SUN, cz);
  sun.target.position.copy(lc);
  sun.position.copy(lc).addScaledVector(SUN, 300);
  sun.target.updateMatrixWorld();
  sun.updateMatrixWorld();
  sunViewDir.value.copy(SUN).transformDirection(camera.matrixWorldInverse);
}

const T0 = 6;
const start = performance.now();
let first = true;

function frame(now: number): void {
  const t = T0 + (now - start) / 1000;
  updateCamera(t);
  updateLighting();
  sky.position.copy(camera.position);
  renderer.render(scene, camera);
  if (first) {
    first = false;
    window.__EVAL_READY__ = true;
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
